        "title": "Confirm Redis Memory Exhaustion and Identify Hot Keys",
        "description": "Collect real\u2011time memory metrics from the Redis primary and enumerate keys consuming the most memory.",
        "commands": [
          "kubectl exec -n cache redis-primary-0 -- redis-cli INFO memory",
          "kubectl exec -n cache redis-primary-0 -- redis-cli --scan | while read key; do echo \"$key $(kubectl exec -n cache redis-primary-0 -- redis-cli MEMORY USAGE $key)\"; done | sort -k2 -n -r | head -20"
