        "verification": [
          "\"used_memory\" > 98% of \"maxmemory\"",
          "Top 20 keys account for > 60% of used memory"
        ]
      },
      {
        "step_number": 3,
        "title": "Apply Write\u2011Freeze and Promote Read\u2011Replica to Primary",
        "description": "Prevent further writes to the exhausted primary, promote the healthy read\u2011replica, and point the service to the new primary.",
        "commands": [
          "# Enable write\u2011freeze (application\u2011level flag)",
          "curl -X POST -H \"Authorization: Bearer $TOKEN\" https://inventory-api.internal/admin/write-freeze",
          "# Promote replica",
          "kubectl exec -n cache redis-replica-0 -- redis-cli -p 6379 REPLICAOF NO ONE",
          "# Update Service Endpoint (if using a ConfigMap)",
          "kubectl patch configmap inventory-api-config -n prod --type merge -p '{\"data\":{\"REDIS_HOST\":\"redis-replica-0.cache.svc.cluster.local\"}}'"
        ],
        "verification": [
          "Write\u2011freeze endpoint returns status 200",
          "Replica reports role \"master\" in INFO replication",
          "ConfigMap reflects new REDIS_HOST value"
        ]
      },
      {
        "step_number": 4,
        "title": "Increase Redis Maxmemory Limit and Adjust Eviction Policy",
        "description": "Raise the maxmemory setting to accommodate current load and switch to an eviction policy that safely discards least\u2011recently\u2011used keys.",
        "commands": [
          "kubectl edit statefulset redis-primary -n cache",
          "# In the container args, add or modify:",
          "#   --maxmemory 4gb",
          "#   --maxmemory-policy allkeys-lru",
          "kubectl rollout restart statefulset/redis-primary -n cache"
        ],
        "verification": [
          "After pod restart, `redis-cli CONFIG GET maxmemory` returns >= 4gb",
          "`redis-cli CONFIG GET maxmemory-policy` returns \"allkeys-lru\"",
          "Memory usage stabilises below 80% of maxmemory within 5 minutes"
        ]
      },
      {
        "step_number": 5,
        "title": "Perform Graceful Rolling Restart of Inventory\u2011API Pods",
        "description": "Refresh the API pods so they reconnect to the newly promoted Redis primary and pick up the updated configuration.",
        "commands": [
          "kubectl rollout restart deployment/inventory-api -n prod",
          "kubectl rollout status deployment/inventory-api -n prod --timeout=5m"
        ],
        "verification": [
          "All inventory\u2011api pods report READY=1/1 and STATUS=Running",
          "Health endpoint returns HTTP 200",
          "Application logs no longer contain ERR_STORAGE_EXHAUSTION_333"
        ]
      }
    ],
    "rollback_plan": {
      "overall_strategy": "Revert Redis configuration and primary/replica roles to their pre\u2011remediation state, and undo the inventory\u2011api deployment rollout if service health degrades.",
      "steps": [
        {
          "step_number": 1,
          "description": "Disable write\u2011freeze to allow normal write traffic.",
          "commands": [
            "curl -X POST -H \"Authorization: Bearer $TOKEN\" https://inventory-api.internal/admin/write-unfreeze"
          ],
          "verification": [
            "Write\u2011freeze endpoint returns status 200 and confirms disabled"
          ]
        },
        {
          "step_number": 2,
          "description": "Demote the promoted replica back to read\u2011only and re\u2011promote the original primary.",
          "commands": [
            "kubectl exec -n cache redis-replica-0 -- redis-cli REPLICAOF $(kubectl get svc redis-primary -n cache -o jsonpath='{.spec.clusterIP}') 6379",
            "kubectl exec -n cache redis-primary-0 -- redis-cli REPLICAOF NO ONE"
          ],
          "verification": [
            "Original primary reports role \"master\" in INFO replication",
            "Former replica reports role \"slave\""
          ]
        },
        {
          "step_number": 3,
          "description": "Restore original Redis maxmemory and eviction policy.",
          "commands": [
            "kubectl edit statefulset redis-primary -n cache",
            "# Revert args to previous values, e.g., --maxmemory 2gb --maxmemory-policy noeviction",
            "kubectl rollout restart statefulset/redis-primary -n cache"
          ],
          "verification": [
            "`redis-cli CONFIG GET maxmemory` matches pre\u2011remediation value",
            "`redis-cli CONFIG GET maxmemory-policy` matches pre\u2011remediation value"
          ]
        },
        {
          "step_number": 4,
          "description": "Undo inventory\u2011api deployment to previous image tag.",
          "commands": [
